import { useCallback, useEffect, useMemo, useState } from "preact/hooks";
import { CompanionClient } from "@tachyon-companion/api-client";
import {
  COMPANION_PROTOCOL_VERSION,
  type ApprovalSummary,
  type CompanionAgentRow,
} from "@tachyon-companion/protocol";

const STORAGE_KEY = "tachyon.companion.mobile.session.v1";
const APP_VERSION = "0.2.0";
const POLL_MS = 8_000;

interface StoredSession {
  baseUrl: string;
  sessionToken: string;
  expiresAt?: string;
  engineLabel?: string;
}

/** Parse Control "Copy QR payload" JSON (schemaVersion 1). */
function parsePairPayload(raw: string): {
  baseUrl?: string;
  baseUrls?: string[];
  pairCode?: string;
  protocolVersion?: number;
} | null {
  const text = raw.trim();
  if (!text) return null;
  try {
    const j = JSON.parse(text) as Record<string, unknown>;
    if (j && typeof j === "object") {
      const baseUrl = typeof j.baseUrl === "string" ? j.baseUrl : undefined;
      const pairCode = typeof j.pairCode === "string" ? j.pairCode : undefined;
      const protocolVersion = typeof j.protocolVersion === "number" ? j.protocolVersion : undefined;
      const baseUrls = Array.isArray(j.baseUrls)
        ? j.baseUrls.filter((u): u is string => typeof u === "string")
        : undefined;
      if (baseUrl || pairCode) return { baseUrl, baseUrls, pairCode, protocolVersion };
    }
  } catch {
    /* not JSON */
  }
  return null;
}

function loadSession(): StoredSession | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const j = JSON.parse(raw) as StoredSession;
    if (j?.baseUrl && j?.sessionToken) return j;
  } catch {
    /* ignore */
  }
  return null;
}

function saveSession(s: StoredSession | null): void {
  if (!s) localStorage.removeItem(STORAGE_KEY);
  else localStorage.setItem(STORAGE_KEY, JSON.stringify(s));
}

function attentionClass(attention: string): string {
  const a = attention.toLowerCase();
  if (a.includes("needs-input") || a.includes("needs_input")) return "att-needs";
  if (a.includes("working") || a.includes("busy")) return "att-work";
  if (a.includes("throttl")) return "att-throttle";
  if (a.includes("idle") || a.includes("ready")) return "att-idle";
  return "att-unknown";
}

export function App() {
  const [session, setSession] = useState<StoredSession | null>(() => loadSession());
  const [payload, setPayload] = useState("");
  const [baseUrl, setBaseUrl] = useState("");
  const [pairCode, setPairCode] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [statusLine, setStatusLine] = useState<string | null>(null);

  const [agents, setAgents] = useState<CompanionAgentRow[]>([]);
  const [approvals, setApprovals] = useState<ApprovalSummary[]>([]);
  const [selectedAgent, setSelectedAgent] = useState<string | null>(null);
  const [promptText, setPromptText] = useState("");
  const [liveMode, setLiveMode] = useState<"sse" | "poll" | "off">("off");
  const [tab, setTab] = useState<"fleet" | "approvals">("fleet");

  const client = useMemo(() => new CompanionClient(), []);

  const bindClient = useCallback(
    (s: StoredSession) => {
      client.setBaseUrl(s.baseUrl);
      client.setSession(s.sessionToken);
    },
    [client],
  );

  useEffect(() => {
    if (session) bindClient(session);
  }, [session, bindClient]);

  // One-QR dogfood: engine serves this app at /companion/app/#pair=<payload>
  // Camera scan opens the URL; we auto-pair and clear the hash (pair code hygiene).
  useEffect(() => {
    if (session) return;
    const hash = typeof location !== "undefined" ? location.hash : "";
    if (!hash.startsWith("#pair=")) return;
    let raw = "";
    try {
      raw = decodeURIComponent(hash.slice("#pair=".length));
    } catch {
      setError("Invalid pair link in URL.");
      return;
    }
    try {
      history.replaceState(null, "", `${location.pathname}${location.search}`);
    } catch {
      /* ignore */
    }
    const parsed = parsePairPayload(raw);
    if (!parsed?.baseUrl || !parsed?.pairCode) {
      setError("Pair link missing baseUrl or pairCode.");
      return;
    }
    setPayload(raw);
    setBaseUrl(parsed.baseUrl);
    setPairCode(parsed.pairCode);
    setBusy(true);
    setError(null);
    const url = parsed.baseUrl.replace(/\/+$/, "");
    client.setBaseUrl(url);
    void client
      .pair({
        pairCode: parsed.pairCode,
        protocolVersion: parsed.protocolVersion ?? COMPANION_PROTOCOL_VERSION,
        client: { kind: "mobile", name: "Tachyon Companion Mobile", version: APP_VERSION },
      })
      .then((res) => {
        if (res.ok) {
          const next: StoredSession = {
            baseUrl: url,
            sessionToken: res.sessionToken,
            expiresAt: res.expiresAt,
            engineLabel: res.engine?.label,
          };
          saveSession(next);
          setSession(next);
          setStatusLine(`Paired with ${res.engine?.label ?? "engine"}`);
        } else {
          setError(res.message || res.code || "Auto-pair from QR failed.");
        }
      })
      .finally(() => setBusy(false));
  }, [session, client]);

  const clearSession = useCallback(() => {
    saveSession(null);
    setSession(null);
    setAgents([]);
    setApprovals([]);
    setSelectedAgent(null);
    setStatusLine(null);
    setLiveMode("off");
  }, []);

  const loadApprovals = useCallback(async () => {
    if (!session) return;
    bindClient(session);
    try {
      const res = await client.listApprovals();
      if (res.ok) {
        setApprovals(res.approvals.filter((a) => a.status === "pending"));
      }
    } catch {
      /* best-effort */
    }
  }, [session, client, bindClient]);

  const loadAgents = useCallback(async () => {
    if (!session) return;
    bindClient(session);
    try {
      const res = await client.listAgents();
      if (res.ok) {
        setAgents(res.agents);
        setStatusLine(`agents=${res.agents.length}`);
      } else if (res.code === "unpaired" || res.code === "expired") {
        clearSession();
        setError(res.message);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  }, [session, client, bindClient, clearSession]);

  // Live roster: prefer SSE; fall back to poll.
  useEffect(() => {
    if (!session) return;
    bindClient(session);
    const ac = new AbortController();
    let pollTimer: ReturnType<typeof setInterval> | undefined;
    let stopped = false;

    const startPoll = () => {
      setLiveMode("poll");
      void loadAgents();
      void loadApprovals();
      pollTimer = setInterval(() => {
        void loadAgents();
        void loadApprovals();
      }, POLL_MS);
    };

    (async () => {
      try {
        setLiveMode("sse");
        for await (const ev of client.liveEvents(ac.signal)) {
          if (stopped) break;
          if (ev.type === "snapshot") {
            setAgents(ev.state.agents);
            setStatusLine(`live seq=${ev.state.seq}`);
            if (ev.state.connection.status === "expired" || ev.state.connection.status === "disconnected") {
              clearSession();
              break;
            }
          } else if (ev.type === "approvals.changed") {
            void loadApprovals();
          } else if (ev.type === "session") {
            if (ev.reason === "unpaired" || ev.reason === "expired") {
              clearSession();
              break;
            }
          } else if (ev.type === "heartbeat") {
            setStatusLine(`live · heartbeat ${ev.seq}`);
          }
        }
        // Stream ended without abort → poll
        if (!stopped && !ac.signal.aborted) startPoll();
      } catch {
        if (!stopped && !ac.signal.aborted) startPoll();
      }
    })();

    // Initial approvals fetch even under SSE
    void loadApprovals();

    return () => {
      stopped = true;
      ac.abort();
      if (pollTimer) clearInterval(pollTimer);
    };
  }, [session, client, bindClient, loadAgents, loadApprovals, clearSession]);

  const onPastePayload = useCallback((text: string) => {
    setPayload(text);
    const parsed = parsePairPayload(text);
    if (parsed?.baseUrl) setBaseUrl(parsed.baseUrl);
    if (parsed?.pairCode) setPairCode(parsed.pairCode);
  }, []);

  const pair = useCallback(async () => {
    setError(null);
    setBusy(true);
    try {
      const parsed = parsePairPayload(payload);
      const url = (baseUrl || parsed?.baseUrl || "").replace(/\/+$/, "");
      const code = (pairCode || parsed?.pairCode || "").trim();
      if (!url || !code) {
        setError("Need base URL and pair code (or paste Control QR payload).");
        return;
      }
      if (!/^https?:\/\//i.test(url)) {
        setError("Base URL must start with http:// or https://");
        return;
      }
      client.setBaseUrl(url);
      const res = await client.pair({
        pairCode: code,
        protocolVersion: parsed?.protocolVersion ?? COMPANION_PROTOCOL_VERSION,
        client: { kind: "mobile", name: "Tachyon Companion Mobile", version: APP_VERSION },
      });
      if (res.ok) {
        const next: StoredSession = {
          baseUrl: url,
          sessionToken: res.sessionToken,
          expiresAt: res.expiresAt,
          engineLabel: res.engine?.label,
        };
        saveSession(next);
        setSession(next);
        setStatusLine(`Paired with ${res.engine?.label ?? "engine"}`);
        return;
      }
      const alts = (parsed?.baseUrls ?? []).filter((u) => u.replace(/\/+$/, "") !== url);
      setError(
        (res.message || res.code || "Pair failed.") +
          (alts.length
            ? ` Try another candidate URL from Control (e.g. ${alts[0]}) if this host is unreachable.`
            : ""),
      );
    } finally {
      setBusy(false);
    }
  }, [baseUrl, pairCode, payload, client]);

  const sendPrompt = useCallback(async () => {
    if (!session || !selectedAgent) return;
    const text = promptText.trim();
    if (!text) {
      setError("Prompt is empty.");
      return;
    }
    if (text.length > 4000) {
      setError("Prompt too long (max 4000 characters).");
      return;
    }
    if (!window.confirm(`Send prompt to agent “${selectedAgent}”?`)) return;
    setBusy(true);
    setError(null);
    try {
      bindClient(session);
      // Revalidate agent still listed (stale selection after fleet churn).
      const roster = await client.listAgents();
      if (roster.ok && !roster.agents.some((a) => a.name === selectedAgent)) {
        setError(`Agent “${selectedAgent}” is no longer running. Refresh fleet.`);
        setAgents(roster.agents);
        setSelectedAgent(null);
        return;
      }
      const res = await client.sendPrompt(selectedAgent, text);
      if (res.ok) {
        setPromptText("");
        setStatusLine(`prompt → ${res.agent} (${res.status})`);
        void loadAgents();
      } else {
        setError(res.message || res.code);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(false);
    }
  }, [session, selectedAgent, promptText, client, bindClient, loadAgents]);

  const resolveApproval = useCallback(
    async (id: string, decision: "approved" | "denied", summary: string) => {
      if (!session) return;
      const label = decision === "approved" ? "ACCEPT" : "DENY";
      if (!window.confirm(`${label} approval?\n\n${summary.slice(0, 280)}`)) return;
      setBusy(true);
      setError(null);
      try {
        bindClient(session);
        const res = await client.resolveApproval({ id, decision });
        if (res.ok) {
          setStatusLine(`approval ${id} → ${res.status}`);
          // Optimistic drop; authoritative refresh follows.
          setApprovals((prev) => prev.filter((a) => a.id !== id));
          void loadApprovals();
        } else {
          setError(res.message || res.code);
          void loadApprovals();
        }
      } catch (e) {
        setError(e instanceof Error ? e.message : String(e));
      } finally {
        setBusy(false);
      }
    },
    [session, client, bindClient, loadApprovals],
  );

  const unpair = useCallback(async () => {
    setBusy(true);
    try {
      if (session) {
        bindClient(session);
        await client.unpair();
      }
    } finally {
      clearSession();
      setBusy(false);
    }
  }, [session, client, bindClient, clearSession]);

  return (
    <div class="shell">
      <h1>Tachyon Companion</h1>
      <p class="sub">Mobile · fleet · prompts · approvals (SDD 422)</p>

      {!session ? (
        <div class="card">
          <label htmlFor="payload">Paste QR payload from Control</label>
          <textarea
            id="payload"
            data-testid="pair-payload"
            placeholder='{"type":"tachyon.companion.pair","schemaVersion":1,...}'
            value={payload}
            onInput={(e) => onPastePayload((e.target as HTMLTextAreaElement).value)}
          />
          <label htmlFor="baseUrl">Base URL</label>
          <input
            id="baseUrl"
            data-testid="pair-base-url"
            placeholder="http://192.168.x.x:41000"
            value={baseUrl}
            onInput={(e) => setBaseUrl((e.target as HTMLInputElement).value)}
          />
          <label htmlFor="code">Pair code</label>
          <input
            id="code"
            data-testid="pair-code"
            placeholder="ABCD2345"
            autoCapitalize="characters"
            value={pairCode}
            onInput={(e) => setPairCode((e.target as HTMLInputElement).value)}
          />
          {error ? <p class="err">{error}</p> : null}
          <button type="button" data-testid="pair-submit" disabled={busy} onClick={() => void pair()}>
            {busy ? "Pairing…" : "Pair"}
          </button>
          <p class="hint" style={{ marginTop: "0.75rem" }}>
            On the PC: enable <span class="mono">settings.companion.lanAccess: true</span>, Control → Companion → Show
            pair code, paste payload here. Same Wi‑Fi.
          </p>
        </div>
      ) : (
        <>
          <div class="card">
            <p class="ok">Connected{liveMode !== "off" ? ` · ${liveMode}` : ""}</p>
            <div class="row">
              <span>Engine</span>
              <span class="mono">{session.engineLabel ?? "—"}</span>
            </div>
            <div class="row">
              <span>Base URL</span>
              <span class="mono">{session.baseUrl}</span>
            </div>
            {statusLine ? <p class="hint">{statusLine}</p> : null}
            {error ? <p class="err">{error}</p> : null}
            <div class="btn-row">
              <button type="button" class="secondary" disabled={busy} onClick={() => void loadAgents()}>
                Refresh
              </button>
              <button type="button" class="danger" disabled={busy} onClick={() => void unpair()}>
                Unpair
              </button>
            </div>
          </div>

          <div class="tabs" data-testid="main-tabs">
            <button
              type="button"
              class={tab === "fleet" ? "tab on" : "tab"}
              data-testid="tab-fleet"
              onClick={() => setTab("fleet")}
            >
              Fleet ({agents.length})
            </button>
            <button
              type="button"
              class={tab === "approvals" ? "tab on" : "tab"}
              data-testid="tab-approvals"
              onClick={() => setTab("approvals")}
            >
              Approvals ({approvals.length})
            </button>
          </div>

          {tab === "fleet" ? (
            <>
              <div class="card" data-testid="agent-roster">
                <h2 class="card-title">Agents</h2>
                {agents.length === 0 ? (
                  <p class="hint">No running agents (or still loading).</p>
                ) : (
                  <ul class="agent-list">
                    {agents.map((a) => (
                      <li key={a.name}>
                        <button
                          type="button"
                          class={selectedAgent === a.name ? "agent-row selected" : "agent-row"}
                          data-testid="agent-row"
                          data-agent={a.name}
                          onClick={() => setSelectedAgent(a.name)}
                        >
                          <span class="agent-name mono">{a.name}</span>
                          <span class={`badge ${attentionClass(a.attention)}`}>{a.attention}</span>
                          {a.composerOccupied ? <span class="badge att-work">composer</span> : null}
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>

              {selectedAgent ? (
                <div class="card" data-testid="prompt-panel">
                  <h2 class="card-title">Prompt → {selectedAgent}</h2>
                  <label htmlFor="prompt">Message (idle-safe send)</label>
                  <textarea
                    id="prompt"
                    data-testid="prompt-text"
                    placeholder="Short message for the agent…"
                    value={promptText}
                    onInput={(e) => setPromptText((e.target as HTMLTextAreaElement).value)}
                  />
                  <button
                    type="button"
                    data-testid="prompt-send"
                    disabled={busy || !promptText.trim()}
                    onClick={() => void sendPrompt()}
                  >
                    {busy ? "Sending…" : "Send prompt"}
                  </button>
                </div>
              ) : null}
            </>
          ) : (
            <div class="card" data-testid="approvals-panel">
              <h2 class="card-title">Pending approvals</h2>
              {approvals.length === 0 ? (
                <p class="hint">No pending approvals.</p>
              ) : (
                <ul class="approval-list">
                  {approvals.map((a) => (
                    <li key={a.id} class="approval-item" data-testid="approval-item">
                      <div class="row">
                        <span class="mono">{a.id.slice(0, 12)}…</span>
                        <span class="badge att-needs">{a.risk}</span>
                      </div>
                      <p class="approval-reason">{a.reason}</p>
                      <p class="hint mono">{a.proposedAction}</p>
                      {a.exactPrompt ? <p class="hint">{a.exactPrompt}</p> : null}
                      <div class="btn-row">
                        <button
                          type="button"
                          data-testid="approval-approve"
                          disabled={busy}
                          onClick={() =>
                            void resolveApproval(a.id, "approved", `${a.reason}\n${a.proposedAction}`)
                          }
                        >
                          Accept
                        </button>
                        <button
                          type="button"
                          class="danger"
                          data-testid="approval-deny"
                          disabled={busy}
                          onClick={() =>
                            void resolveApproval(a.id, "denied", `${a.reason}\n${a.proposedAction}`)
                          }
                        >
                          Deny
                        </button>
                      </div>
                    </li>
                  ))}
                </ul>
              )}
              <button type="button" class="secondary" disabled={busy} onClick={() => void loadApprovals()}>
                Refresh approvals
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}
